var rows = $input.all();

var statusCounts  = {};
var monthCounts   = {};
var nightsByStatus = {};

rows.forEach(function(r) {
  var status   = r.json['Status']   || 'Pending';
  var nights   = parseInt(r.json['Nights'] || '0', 10) || 0;
  var received = String(r.json['Received'] || '');

  statusCounts[status]   = (statusCounts[status]   || 0) + 1;
  nightsByStatus[status] = (nightsByStatus[status] || 0) + nights;

  if (received.length >= 7) {
    var month = received.substring(0, 7); // YYYY-MM
    monthCounts[month] = (monthCounts[month] || 0) + 1;
  }
});

var lines = [];

lines.push('# HELP wg_gesucht_requests_total Current rental requests by status');
lines.push('# TYPE wg_gesucht_requests_total gauge');
['Pending', 'Accepted', 'Declined'].forEach(function(s) {
  lines.push('wg_gesucht_requests_total{status="' + s + '"} ' + (statusCounts[s] || 0));
});

lines.push('# HELP wg_gesucht_requests_monthly Requests received per calendar month');
lines.push('# TYPE wg_gesucht_requests_monthly gauge');
Object.keys(monthCounts).sort().forEach(function(m) {
  lines.push('wg_gesucht_requests_monthly{month="' + m + '"} ' + monthCounts[m]);
});

lines.push('# HELP wg_gesucht_nights_requested Total nights requested by status');
lines.push('# TYPE wg_gesucht_nights_requested gauge');
['Pending', 'Accepted', 'Declined'].forEach(function(s) {
  lines.push('wg_gesucht_nights_requested{status="' + s + '"} ' + (nightsByStatus[s] || 0));
});

lines.push('');
return [{ json: { metrics: lines.join('\n') } }];
